<?php require_once __DIR__.'/../../models/InscripcionModel.php';$ins=es_estudiante()?[]:(new InscripcionModel($pdo))->obtenerTodas();include __DIR__.'/../layouts/header.php';$puedeGestionar=puede_gestionar_academico();?><div class="toolbar"><div><h1 class="page-title">Asistencia</h1><p class="subtitle">Control de presencia, ausencias y tardanzas.</p></div><?php if($puedeGestionar):?><a class="btn btn-primary" href="?accion=crear">+ Registrar asistencia</a><?php endif;?></div><div class="card"><div class="card-body"><input class="search" data-search="#tabla" placeholder="Buscar estudiante o curso..."><div class="table-wrap"><table class="table" id="tabla"><thead><tr><th>Estudiante</th><th>Curso</th><th>Fecha</th><th>Estado</th><th>Observación</th><?php if($puedeGestionar):?><th>Acciones</th><?php endif;?></tr></thead><tbody><?php foreach($registros as $r):?><tr><td><?=e($r['estudiante'])?></td><td><?=e($r['codigo'])?></td><td><?=e($r['fecha'])?></td><td><span class="badge <?=in_array($r['estado'],['presente','justificado'])?'badge-success':($r['estado']==='tarde'?'badge-warning':'badge-danger')?>"><?=e($r['estado'])?></span></td><td><?=e($r['observacion'])?></td><?php if($puedeGestionar):?><td><div class="actions"><a class="btn btn-light btn-sm" href="?accion=editar&id=<?=$r['id_asistencia']?>">Editar</a><form method="post" onsubmit="return confirm('¿Eliminar registro de asistencia?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="accion" value="eliminar"><input type="hidden" name="id" value="<?=$r['id_asistencia']?>"><button class="btn btn-danger btn-sm">Eliminar</button></form></div></td><?php endif;?></tr><?php endforeach;?></tbody></table></div></div></div><?php if($puedeGestionar && $accion!=='listar'):?><div class="card" style="margin-top:18px"><div class="card-body"><h2 style="margin-top:0"><?= $registro?'Editar':'Registrar'?> asistencia</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="accion" value="guardar"><div class="grid grid-2"><div class="form-group"><label class="form-label">Inscripción</label><select required name="id_inscripcion"><?php foreach($ins as $i):?><option value="<?=$i['id_inscripcion']?>" <?=($registro['id_inscripcion']??'')==$i['id_inscripcion']?'selected':''?>><?=e($i['estudiante'].' · '.$i['codigo'].' · '.$i['nombre_curso'])?></option><?php endforeach;?></select></div><div class="form-group"><label class="form-label">Fecha</label><input required type="date" name="fecha" value="<?=e($registro['fecha']??date('Y-m-d'))?>"></div><div class="form-group"><label class="form-label">Estado</label><select name="estado"><option value="presente">Presente</option><option value="ausente">Ausente</option><option value="justificado">Justificado</option><option value="tarde">Tarde</option></select></div><div class="form-group"><label class="form-label">Observación</label><input name="observacion" value="<?=e($registro['observacion']??'')?>"></div></div><div class="actions"><button class="btn btn-primary">Guardar</button><a class="btn btn-light" href="/controllers/asistencia.php">Cancelar</a></div></form></div></div><?php endif;?><?php include __DIR__.'/../layouts/footer.php';?>
